import{_ as e,o as d,c as a,a6 as o}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"流与多路复用","description":"流 ID 分配规则、七态状态机与多路复用如何消除应用层队头阻塞。","frontmatter":{"title":"流与多路复用","description":"流 ID 分配规则、七态状态机与多路复用如何消除应用层队头阻塞。","source":"https://daiw.org/manual/http2-3/h2-streams"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h2-streams.md","filePath":"manual/computer-programming/http2-3/h2-streams.md"}'),n={name:"manual/computer-programming/http2-3/h2-streams.md"};function r(s,t,c,l,p,i){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="流与多路复用" tabindex="-1">流与多路复用 <a class="header-anchor" href="#流与多路复用" aria-label="Permalink to &quot;流与多路复用&quot;">​</a></h1><p>流 ID 分配规则、七态状态机与多路复用如何消除应用层队头阻塞。</p><h2 id="流是什么" tabindex="-1">流是什么 <a class="header-anchor" href="#流是什么" aria-label="Permalink to &quot;流是什么&quot;">​</a></h2><p><strong>流（stream）</strong> 是一条连接内的独立双向帧序列，承载一个请求/响应交换。一条 h2 连接上可<strong>并发</strong>存在成百上千个流。</p><p>这是 h2 最核心的改进——直接消灭了 1.1 <a href="/Front2Full/manual/computer-programming/http11/connection-management">流水线</a>的两个致命缺陷：</p><table tabindex="0"><thead><tr><th>1.1 流水线</th><th>h2 流</th></tr></thead><tbody><tr><td>响应<strong>必须按请求顺序</strong>返回（无标识符）</td><td>帧带 Stream ID，<strong>响应可任意顺序</strong></td></tr><tr><td>一个慢响应堵住其后所有响应</td><td>各流独立，互不阻塞</td></tr><tr><td>无法取消单个请求</td><td><code>RST_STREAM</code> 单独终止</td></tr><tr><td>浏览器实际禁用</td><td>默认启用</td></tr></tbody></table><h2 id="流-id-分配" tabindex="-1">流 ID 分配 <a class="header-anchor" href="#流-id-分配" aria-label="Permalink to &quot;流 ID 分配&quot;">​</a></h2><p>31 位无符号整数，规则是硬性的：</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td><code>0</code></td><td>保留给<strong>连接级</strong>控制帧（<code>SETTINGS</code>、<code>PING</code>、<code>GOAWAY</code>、连接级 <code>WINDOW_UPDATE</code>）</td></tr><tr><td><strong>奇数</strong></td><td><strong>客户端</strong>发起</td></tr><tr><td><strong>偶数</strong></td><td><strong>服务端</strong>发起（仅 <code>PUSH_PROMISE</code>，已废弃）</td></tr><tr><td>单调递增</td><td>新建流的 ID <strong>MUST</strong> 大于本端已用过的所有 ID</td></tr></tbody></table><p>关键推论：</p><ul><li>使用<strong>小于等于</strong>已用 ID 的新流 → <code>PROTOCOL_ERROR</code>。</li><li>ID 只增不减，<strong>不可复用</strong>。耗尽 2^31 后 <strong>MUST</strong> 建立新连接——长连接的服务端应主动 <code>GOAWAY</code> 让客户端重连。</li><li>客户端首个流通常是 <strong>1</strong>。</li></ul><h2 id="状态机" tabindex="-1">状态机 <a class="header-anchor" href="#状态机" aria-label="Permalink to &quot;状态机&quot;">​</a></h2><p>七个状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>进入方式</th></tr></thead><tbody><tr><td><code>idle</code></td><td>初始态，任何未用流 ID 的默认状态</td><td>—</td></tr><tr><td><code>reserved (local)</code></td><td>本端已发 <code>PUSH_PROMISE</code> 预留</td><td>推送（已废弃）</td></tr><tr><td><code>reserved (remote)</code></td><td>对端已发 <code>PUSH_PROMISE</code> 预留</td><td>推送（已废弃）</td></tr><tr><td><code>open</code></td><td>双向均可收发</td><td>收/发 <code>HEADERS</code></td></tr><tr><td><code>half-closed (local)</code></td><td>本端已发 <code>END_STREAM</code>，只能收</td><td>发 <code>END_STREAM</code></td></tr><tr><td><code>half-closed (remote)</code></td><td>对端已发 <code>END_STREAM</code>，只能发</td><td>收 <code>END_STREAM</code></td></tr><tr><td><code>closed</code></td><td>终态</td><td>双向 <code>END_STREAM</code>，或 <code>RST_STREAM</code></td></tr></tbody></table><p>典型请求的迁移路径：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端视角:</span></span>
<span class="line"><span>  idle</span></span>
<span class="line"><span>   → (发 HEADERS)            open</span></span>
<span class="line"><span>   → (发 DATA[END_STREAM])   half-closed (local)</span></span>
<span class="line"><span>   → (收 HEADERS + DATA)     ...</span></span>
<span class="line"><span>   → (收 END_STREAM)         closed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>半关闭是常态</strong>：客户端发完请求即进入 <code>half-closed (local)</code>，此后只接收响应。这与 1.1 的 TCP 半关闭是不同层次的概念。</p><h3 id="状态相关的错误" tabindex="-1">状态相关的错误 <a class="header-anchor" href="#状态相关的错误" aria-label="Permalink to &quot;状态相关的错误&quot;">​</a></h3><ul><li>向 <code>closed</code> 流发帧 → <code>STREAM_CLOSED</code>。</li><li>在 <code>half-closed (remote)</code> 上收到 <code>DATA</code>/<code>HEADERS</code> → <code>STREAM_CLOSED</code>。</li><li>因竞态在刚关闭的流上收到少量帧属<strong>正常现象</strong>——接收方 <strong>SHOULD</strong> 在一段时间内宽容忽略，而非立刻杀掉整条连接。</li></ul><h2 id="并发上限" tabindex="-1">并发上限 <a class="header-anchor" href="#并发上限" aria-label="Permalink to &quot;并发上限&quot;">​</a></h2><p><code>SETTINGS_MAX_CONCURRENT_STREAMS</code> 限制<strong>对端</strong>可同时打开的流数：</p><ul><li>默认<strong>无限制</strong>——但双方都 <strong>SHOULD</strong> 设置有限值（常见 100–128）。</li><li>只计 <code>open</code> 与两种 <code>half-closed</code> 状态的流；<code>closed</code> 与 <code>idle</code> 不计。</li><li>超限时接收方 <strong>MAY</strong> 用 <code>REFUSED_STREAM</code> 或 <code>PROTOCOL_ERROR</code> 拒绝。</li><li>该值调小时，已存在的超限流<strong>不必</strong>关闭，但不得再开新流。</li></ul><p><code>REFUSED_STREAM</code> 有特殊价值：它<strong>明确保证服务端未处理该请求</strong>，因此客户端可以<strong>自动重试任何方法</strong>（含非幂等的 <code>POST</code>）——这是 1.1 完全没有的确定性。</p><h2 id="多路复用的实际收益" tabindex="-1">多路复用的实际收益 <a class="header-anchor" href="#多路复用的实际收益" aria-label="Permalink to &quot;多路复用的实际收益&quot;">​</a></h2><p>对同一域下 100 个小资源：</p><table tabindex="0"><thead><tr><th></th><th>1.1（6 条连接）</th><th>h2（1 条连接）</th></tr></thead><tbody><tr><td>TCP 握手</td><td>6 次</td><td>1 次</td></tr><tr><td>TLS 握手</td><td>6 次</td><td>1 次</td></tr><tr><td>并发上限</td><td>6</td><td>100+</td></tr><tr><td>头部字节</td><td>100 × 全量</td><td>首个全量，其余增量（<a href="/Front2Full/manual/computer-programming/http2-3/hpack">HPACK</a>）</td></tr><tr><td>单个慢资源</td><td>阻塞其所在连接的队列</td><td>只影响自己</td></tr></tbody></table><p>副作用：<strong>域名分片（domain sharding）成了反模式</strong>。1.1 时代把资源拆到 <code>img1.</code>/<code>img2.</code> 多域以突破 6 连接限制；h2 下这只会增加握手与连接开销，应合并回单域。</p><h2 id="仍然存在的队头阻塞" tabindex="-1">仍然存在的队头阻塞 <a class="header-anchor" href="#仍然存在的队头阻塞" aria-label="Permalink to &quot;仍然存在的队头阻塞&quot;">​</a></h2><p>h2 消除的是 <strong>HTTP 层</strong>的队头阻塞，<strong>TCP 层的仍在</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP 字节流:  [流1帧][流3帧][流1帧][流5帧]</span></span>
<span class="line"><span>                    ↑ 此段丢失</span></span>
<span class="line"><span>结果: 内核在重传补齐前不向应用交付后续任何字节</span></span>
<span class="line"><span>      → 流 3、流 5 明明已完整到达，也必须干等</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>丢包率越高，单连接 h2 越吃亏——极端情况下<strong>不如</strong>多条 1.1 连接（每条连接的丢包只影响自己）。这是 <a href="/Front2Full/manual/computer-programming/http2-3/quic-transport">HTTP/3 改用 QUIC</a> 的唯一动机。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/hpack">HPACK 头部压缩</a>。</p>`,32)])])}const m=e(n,[["render",r]]);export{g as __pageData,m as default};
